        return tokens[pos][1], pos + 1
    elif pos < len(tokens) and tokens[pos][0] == '(':
        pos += 1
        result, pos = parse_expression(tokens, pos)
        if pos < len(tokens) and tokens[pos][0] == ')':
            pos += 1
        return result, pos
    else:
        raise ValueError(f"Unexpected token at position {pos}")

